import{z as s,x as i,o as r,c as d,q as A,j as o,D as e,d as t,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"费用对复合收益","description":"","frontmatter":{"title":"费用对复合收益","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fees-compounding.md","filePath":"quant/fees-compounding.md","lastUpdated":1791063341000}'),p={name:"quant/fees-compounding.md"};function h(m,a,f,u,c,D){const n=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="费用对复合收益" tabindex="-1">费用对复合收益 <a class="header-anchor" href="#费用对复合收益" aria-label="Permalink to &quot;费用对复合收益&quot;">​</a></h1><div class="epigraph"><p>主动投资作为一个整体，在扣费后必须输给被动整体：这是会计恒等式，不是对任何一只基金的预测。</p><footer>—— Sharpe, The Arithmetic of Active Management, Financial Analysts Journal, 1991；社会成本见 French, Journal of Financial Economics, 2008</footer></div><p><a href="/quant/performance-fee-hwm">上一课</a>把激励费写成路径期权。本课的缺口是<strong>管理费、交易成本与激励费如何进入几何收益</strong>。Sharpe 的算术：主动投资者整体持有市场，毛收益相等，费用让主动整体净收益低于被动。French 估计美国主动投资的社会成本。本课把恒等式接到产品：2% 管理费不是从算术均值里减 200bp 那么简单，它与波动拖累、杠杆重置同类，见 <a href="/quant/leverage-volatility-drag">杠杆与波动拖累</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>年费 \\(f\\) 对财富的乘数是 \\((1-f)\\) 每年，或更细的日计提。几何收益近似 \\(\\mu-\\sigma^2/2-f\\)。高波动策略同样的 \\(f\\) 吃掉更多复利，因为净值回撤后费用仍按 AUM 抽。激励费在水位上额外非线性。问题是比较：毛夏普好看的策略，扣费后可能低于便宜的风险平价或指数。ARP 产品若叠加基金费、平台费、指数许可费，边缘见 <a href="/quant/net-edge">净边缘</a>。</p><p><span class="marginnote">数字感受一下复利的牙齿：100 万本金、毛收益 8%，费率 2% 与 0.5%，30 年后终值分别约是 5.7 倍与 8.8 倍——费率差 1.5 个点，终值差三分之一以上，且年份越久差距越大。</span></p><p>与生命周期：衰减的毛 IR 先被费用打穿。产品该停的时点往往是扣费 IR 过零，而不是毛 IR 过零。</p><h3 id="算术主动-vs-单只基金" tabindex="-1">算术主动 vs 单只基金 <a class="header-anchor" href="#算术主动-vs-单只基金" aria-label="Permalink to &quot;算术主动 vs 单只基金&quot;">​</a></h3><p>Sharpe 的恒等式不禁止单只基金扣费后战胜市场，只禁止<strong>全体</strong>主动一起战胜。营销用单只样本路径对抗恒等式，是选择偏差，见 <a href="/quant/deflated-sharpe">放气夏普</a>。评价单只仍要做，但要把费用当确定的负 carry，不是当「如果今年没赚就不算」。</p><p><span class="marginnote">资金加权后，费用发生在 AUM 最大的时候往往最伤——那正是后课资金流追逐业绩的时候。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模拟：日计提管理费 + HWM 激励 + 预估换手成本。输出：净几何、净夏普、相对被动的缺口。对照：把 \\(f\\) 从 0 扫到合同值，看 IR 何时过零。杠杆策略的融资成本与费用分列，不要塞进同一个「损耗」。</p>',12)),(r(),o(l,null,{default:e(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIM%5B%22%E6%97%A5%E8%AE%A1%E6%8F%90%E6%A8%A1%E6%8B%9F%3A%20%E7%AE%A1%E7%90%86%E8%B4%B9%20%2B%20HWM%20%E6%BF%80%E5%8A%B1%20%2B%20%E6%8D%A2%E6%89%8B%E6%88%90%E6%9C%AC%22%5D%20--%3E%20OUT%5B%22%E5%87%80%E5%87%A0%E4%BD%95%20%2F%20%E5%87%80%E5%A4%8F%E6%99%AE%20%2F%20%E5%AF%B9%E8%A2%AB%E5%8A%A8%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20OUT%20--%3E%20SWEEP%7B%22%E8%B4%B9%E7%8E%87%20f%20%E4%BB%8E%200%20%E6%89%AB%E5%88%B0%E5%90%88%E5%90%8C%E5%80%BC%22%7D%0A%20%20SWEEP%20--%3E%7C%22%E5%87%80%20IR%20%E5%A7%8B%E7%BB%88%E5%A4%A7%E4%BA%8E%200%22%7C%20LIVE%5B%22%E5%8F%AF%E5%8F%91%E8%A1%8C%2C%20%E9%A2%84%E7%99%BB%E8%AE%B0%E5%90%8E%E5%86%8D%E9%AA%8C%22%5D%0A%20%20SWEEP%20--%3E%7C%22%E5%87%80%20IR%20%E8%BF%87%E9%9B%B6%22%7C%20STOP%5B%22%E8%A1%B0%E5%87%8F%E7%AD%96%E7%95%A5%E5%BA%94%E5%81%9C%3A%20%E6%89%A3%E8%B4%B9%20IR%20%E6%98%AF%E5%81%9C%E6%8D%9F%E7%BA%BF%22%5D%0A%20%20SWEEP%20--%3E%7C%22%E6%8D%9F%E8%80%97%E6%9D%A5%E6%BA%90%E4%B8%8D%E6%B8%85%22%7C%20SPLIT%5B%22%E8%9E%8D%E8%B5%84%E6%88%90%E6%9C%AC%E4%B8%8E%E8%B4%B9%E7%94%A8%E5%88%86%E5%88%97%E5%86%8D%E5%88%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"费用是对财富过程的连续漏出。凸性（激励费）在正路径上加速漏出，在负路径上留下管理费漏出。复利使早期高费对终值的伤害大于晚期。被动越便宜，主动必须提供的毛 IR 越高——这是算术，不是对技能的否定。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"「早期高费伤害更大」可以类比滚雪球：雪核还小时被抽走一层，那层雪本可以跟着滚三十年；快到终点才抽，损失没时间复利。所以同样的费率，持有期越长，对终值的拖累越夸张。")],-1)),(r(),o(l,null,{default:e(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Gross%5B%22%E6%AF%9B%E6%94%B6%E7%9B%8A%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20Fee%5B%22%E7%AE%A1%E7%90%86%E8%B4%B9%20%E6%BF%80%E5%8A%B1%E8%B4%B9%20%E5%86%B2%E5%87%BB%22%5D%0A%20%20Fee%20--%3E%20Net%5B%22%E5%87%80%E5%87%A0%E4%BD%95%22%5D%0A%20%20Vol%5B%22%E6%B3%A2%E5%8A%A8%E6%8B%96%E7%B4%AF%22%5D%20--%3E%20Net%0A%20%20Arb%5B%22Sharpe%20%E7%AE%97%E6%9C%AF%22%5D%20--%3E%20Bound%5B%22%E4%B8%BB%E5%8A%A8%E6%95%B4%E4%BD%93%E5%87%80%E4%BD%8E%E4%BA%8E%E8%A2%AB%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算税务（见税务感知组合课）也不算业绩费的会计操纵。下一课问扣费后技能是否持续，而不是再讲费用公式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费用进入几何，与波动拖累一起减终值；不是从算术均值里减一个常数。</li><li>主动整体扣费后不可能战胜被动整体（Sharpe 算术）。</li><li>产品停损看扣费 IR，不看毛 IR。</li><li>出处：Sharpe, <em>FAJ</em>, 1991；French, <em>JFE</em>, 2008。</li></ul>',4))])}const _=s(p,[["render",h]]);export{C as __pageData,_ as default};
